{
  "name": "USB2000光谱仪",
  "name_en": "USB2000 spectrometer",
  "manufacturer": "Ocean Insight (Ocean Optics)",
  "description": "Ocean Insight 的 USB2000 光谱仪，用于实验中采集样品的光谱数据，并通过设置积分时间来适配不同信号强度的光学测量。",
  "description_en": "An Ocean Insight USB2000 spectrometer used in laboratory experiments to acquire spectral data and adjust integration time for optical measurements with different signal levels.",
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化 USB2000 光谱仪并建立基本通信状态。",
      "description_en": "Initialize the USB2000 spectrometer and establish its basic communication state."
    },
    {
      "action_name": "auto-getSpectrumData",
      "description": "读取光谱仪采集到的光谱数据。",
      "description_en": "Retrieve the spectral data acquired by the spectrometer."
    },
    {
      "action_name": "auto-setIntegrationTime",
      "description": "设置光谱采集的积分时间。",
      "description_en": "Set the integration time for spectral acquisition."
    }
  ],
  "tag_hints": [
    "UV-Vis spectroscopy",
    "optical spectrum acquisition",
    "integration time control",
    "Ocean Insight spectrometer",
    "USB spectrometer",
    "emission detection"
  ]
}

